import kotlinx.coroutines.*
import kotlinx.coroutines.channels.Channel
import kotlinx.coroutines.flow.*

// 模拟一帧数据（视频帧 / 埋点事件 / 传感器读数）
data class Frame(val id: Int, val bytes: ByteArray = ByteArray(1024))

// 生产端：每 10ms 产出一帧（快）
fun frameSource(total: Int): Flow<Frame> = flow {
    repeat(total) { i ->
        delay(10)
        emit(Frame(i))
    }
}

// 消费端：每帧处理耗时 50ms（慢）
suspend fun processFrame(f: Frame) {
    delay(50)
}

// 计时工具
suspend fun benchmark(name: String, block: suspend () -> Unit) {
    val start = System.currentTimeMillis()
    block()
    println("%-12s %4d ms".format(name, System.currentTimeMillis() - start))
}

// 并发扇出：1 个生产者 -> N 个 worker -> 结果汇回下游
fun fanOut(frames: Flow<Frame>, workers: Int): Flow<String> = channelFlow {
    val queue = Channel<Frame>(capacity = Channel.BUFFERED) // 有界队列 = 背压边界

    // 上游协程：灌数据进队列
    val producer = launch {
        frames.collect { queue.send(it) }
        queue.close() // 生产结束，关闭队列，worker 的 for 循环自然退出
    }

    // N 个 worker 竞争消费
    val jobs = List(workers) { w ->
        launch {
            for (frame in queue) {          // 队列空时挂起，close 后结束
                processFrame(frame)
                send("worker-$w <- frame-${frame.id}") // 汇回 channelFlow 下游
            }
        }
    }

    jobs.joinAll()
    producer.join()
}

fun main() = runBlocking {
    // 同一条管线，四种背压策略的耗时对比
    benchmark("串行")     { frameSource(20).collect { processFrame(it) } }
    benchmark("buffer")   { frameSource(20).buffer(64).collect { processFrame(it) } }
    benchmark("conflate") { frameSource(20).conflate().collect { processFrame(it) } }
    benchmark("latest")   { frameSource(20).collectLatest { processFrame(it) } }

    println("\n--- fan-out with 4 workers ---")
    fanOut(frameSource(8), 4).collect { println(it) }
}

